package com.erp.management.controller;
import com.erp.management.entity.Customer; import com.erp.management.repository.CustomerRepository; import jakarta.validation.Valid; import org.springframework.data.domain.Sort; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/people") public class PeopleController { private final CustomerRepository customers; public PeopleController(CustomerRepository c){customers=c;} @PostMapping("/add") ResponseEntity<Customer> add(@Valid @RequestBody Customer c){c.id=null;return ResponseEntity.status(HttpStatus.CREATED).body(customers.save(c));} @GetMapping("/all") List<Customer> all(){return customers.findAll(Sort.by("name"));} @GetMapping("/{id}") Customer one(@PathVariable Long id){return customers.findById(id).orElseThrow(()->new IllegalArgumentException("Person not found"));} }
